from __future__ import annotations

import io
import json
from pathlib import Path

import pandas as pd


DATASET = Path("/app/dataset")
REPORT_START_UTC = pd.Timestamp("2024-03-15 00:00:00", tz="UTC")
REPORT_END_UTC = pd.Timestamp("2024-03-16 00:00:00", tz="UTC")


def _calibration_config() -> dict:
    with open(DATASET / "sensors_calibration.json") as f:
        data = json.load(f)
    return data["enterprise_platform"]["deployment_environments"]["system_config"]["farms"]


def _farm_metadata() -> pd.DataFrame:
    farms = pd.read_csv(DATASET / "farms.csv")
    registry = pd.read_csv(DATASET / "farm_registry.csv")

    farms["farm_key"] = farms["farm_name"].astype(str).str.strip().str.lower()
    registry["farm_key"] = registry["farm_name"].astype(str).str.strip().str.lower()

    return registry.merge(farms, on="farm_key", how="left").set_index("farm_id")


def _read_production_csv(farm_id: str) -> pd.DataFrame:
    path = DATASET / f"production_{farm_id}.csv"
    raw = path.read_bytes()

    if raw.startswith((b"\xff\xfe", b"\xfe\xff")) or raw[:200].count(b"\x00") > 10:
        text = raw.decode("utf-16")
    else:
        text = raw.decode("utf-8-sig")

    csv_text = "\n".join(text.splitlines()[3:]).replace("timestamp\t", "timestamp")
    header = csv_text.splitlines()[0]
    sep = ";" if header.count(";") > header.count(",") else ","

    read_kwargs = {"sep": sep, "engine": "python"}
    if sep == ";":
        read_kwargs.update({"decimal": ",", "thousands": "."})

    return pd.read_csv(io.StringIO(csv_text), **read_kwargs)


def _parse_local_timestamps(values: pd.Series) -> pd.Series:
    text = values.astype("string").str.strip()
    parsed = pd.Series(pd.NaT, index=values.index, dtype="datetime64[ns]")

    iso_mask = text.str.match(
        r"^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$", na=False
    )
    parsed.loc[iso_mask] = pd.to_datetime(
        text.loc[iso_mask], format="%Y-%m-%d %H:%M:%S", errors="coerce"
    )

    dot_mask = text.str.match(
        r"^\d{2}\.\d{2}\.\d{4} \d{2}:\d{2}:\d{2}$", na=False
    )
    parsed.loc[dot_mask] = pd.to_datetime(
        text.loc[dot_mask], format="%d.%m.%Y %H:%M:%S", errors="coerce"
    )

    return parsed


def _unit_to_kwh_factor(unit: str) -> float:
    normalized = unit.strip().lower()
    factors = {
        "kwh": 1.0,
        "mwh": 1000.0,
        "wh": 0.001,
        "btu": 0.00029307107,
        "kw": 1.0,
    }
    return factors[normalized]


def _sample_hours(local_ts: pd.Series) -> float:
    timestamps = local_ts.dropna().sort_values().drop_duplicates()
    diffs = timestamps.diff().dropna()
    diffs = diffs[(diffs > pd.Timedelta(0)) & (diffs < pd.Timedelta(hours=2))]
    if diffs.empty:
        return 0.0
    return float(diffs.median() / pd.Timedelta(hours=1))


def _maintenance_mask(farm_id: str, local_ts: pd.Series) -> pd.Series:
    mask = pd.Series(False, index=local_ts.index)

    if farm_id == "FARM_C":
        mask |= (local_ts >= pd.Timestamp("2024-03-16 08:00:00")) & (
            local_ts < pd.Timestamp("2024-03-16 12:00:00")
        )
    elif farm_id == "FARM_F":
        mask |= (local_ts >= pd.Timestamp("2024-03-15 12:00:00")) & (
            local_ts < pd.Timestamp("2024-03-15 14:00:00")
        )

    return mask.fillna(False)


def _shutdown_mask(df: pd.DataFrame, local_ts: pd.Series) -> pd.Series:
    temperatures = pd.to_numeric(df["inverter_temperature_C"], errors="coerce")
    spike_times = (
        local_ts[temperatures > 85.0]
        .dropna()
        .sort_values()
        .drop_duplicates()
    )

    mask = pd.Series(False, index=local_ts.index)
    for spike_time in spike_times:
        mask |= (local_ts > spike_time) & (
            local_ts <= spike_time + pd.Timedelta(minutes=45)
        )

    return mask.fillna(False)


def _farm_total_kwh(farm_id: str, metadata: pd.Series, config: dict) -> int:
    try:
        df = _read_production_csv(farm_id)
    except FileNotFoundError:
        return 0

    timestamp_column = next(column for column in df.columns if column.strip() == "timestamp")
    df["_local_ts"] = _parse_local_timestamps(df[timestamp_column])

    df = df.drop_duplicates(subset=["_local_ts"], keep="last")
    local_ts = df["_local_ts"]
    utc_ts = local_ts.dt.tz_localize(
        metadata["timezone"], nonexistent="NaT", ambiguous="NaT"
    ).dt.tz_convert("UTC")

    value_column = config["calibration_data"]["value_column_name"]
    calibration_offset = config["calibration_data"]["calibration_offset"]
    true_value = pd.to_numeric(df[value_column], errors="coerce") - calibration_offset

    valid = (
        utc_ts.notna()
        & (utc_ts >= REPORT_START_UTC)
        & (utc_ts < REPORT_END_UTC)
        & true_value.notna()
        & (true_value >= 0)
        & ~_maintenance_mask(farm_id, local_ts)
        & ~_shutdown_mask(df, local_ts)
    )

    sensor_info = config["sensor_info"]
    multiplier = _unit_to_kwh_factor(sensor_info["unit"])
    if sensor_info["reading_type"].strip().lower() == "power":
        multiplier *= _sample_hours(local_ts)

    return round(float((true_value[valid] * multiplier).sum()))


def answer() -> dict[str, int]:
    configs = _calibration_config()
    metadata = _farm_metadata()

    totals: dict[str, int] = {}
    for farm_id, row in metadata.iterrows():
        if farm_id not in configs or pd.isna(row["timezone"]):
            totals[farm_id] = 0
        else:
            totals[farm_id] = _farm_total_kwh(farm_id, row, configs[farm_id])

    return totals


if __name__ == "__main__":
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)
